<?php require 'config/database.php';require 'config/app.php';$id=(int)($_GET['id']??0);$sql="SELECT r.*,t.name AS tournament_name,t.tournament_date,p.amount,p.status AS pay_status FROM registrations r JOIN tournaments t ON t.tournament_id=r.tournament_id LEFT JOIN payments p ON p.registration_id=r.registration_id WHERE r.registration_id=?";$args=[$id];if(isset($_SESSION['player_id'])){$sql.=" AND r.player_id=?";$args[]=(int)$_SESSION['player_id'];}else{$sql.=" AND 1=0";}$s=$pdo->prepare($sql);$s->execute($args);$r=$s->fetch();$pageTitle='Entry status';require 'includes/header.php';if(!$r):?><div class="empty section"><h2>Entry not found</h2><p>Log in to view your private registration details.</p><a href="login.php" class="btn btn-hot">Log in</a></div><?php else:?><section class="success-hero"><div class="check"><?= $r['status']==='confirmed'?'✓':'…' ?></div><div class="eyebrow"><?= $r['status']==='confirmed'?'ENTRY CONFIRMED':'ENTRY STATUS' ?></div><h1><?= $r['status']==='confirmed'?'YOU’RE IN THE ARENA.':'YOUR ENTRY IS BEING REVIEWED.' ?></h1><p><?= $r['status']==='confirmed'?'Your registration is confirmed. Get your squad ready.':'Your entry remains pending until payment and registration are reviewed.' ?></p></section><section class="box receipt"><div class="eyebrow">REGISTRATION RECEIPT</div><h2><?=e($r['tournament_name'])?></h2><div class="receipt-grid"><?php foreach(['REGISTRATION ID'=>$r['registration_code'],'TEAM NAME'=>$r['team_name'],'TOURNAMENT DATE'=>date('d M Y, g:i A',strtotime($r['tournament_date'])),'ENTRY STATUS'=>str_replace('_',' ',$r['status']),'PAYMENT STATUS'=>str_replace('_',' ',$r['pay_status']??'not required'),'AMOUNT'=>(float)($r['amount']??0)>0?'₹'.number_format($r['amount'],2):'FREE ENTRY'] as $k=>$v):?><div><small><?=e($k)?></small><b><?=e($v)?></b></div><?php endforeach;?></div><div class="actions"><button class="btn btn-quiet" onclick="window.print()">Print receipt</button><a href="dashboard.php" class="btn btn-hot">Back to My Arena</a></div></section><?php endif;require 'includes/footer.php';?>
